async function openConfigForm(existing=null){
 try{
  const x=existing||{},quotaMB=x.user_quota_bytes?Math.round(x.user_quota_bytes/1048576):0,lifeMin=x.user_lifetime_seconds?Math.round(x.user_lifetime_seconds/60):0;
  $('#modalTitle').textContent=existing?'Edit Global Reality config':'New Global Reality config';
  $('#modalFields').innerHTML='<div class="muted">Applies automatically to every current and future Sanaei server.</div><label class="checkRow"><input name="enabled" type="checkbox" '+(x.enabled!==false?'checked':'')+'> Enabled</label><label>Ports — one inbound per port<input name="ports" value="'+esc((x.ports||[443]).join(', '))+'" placeholder="443, 8443, 8654"></label><div class="muted">Inbound count is determined automatically by the number of unique ports.</div><label>Target active users / inbound<input name="target_users_per_inbound" type="number" min="0" value="'+esc(x.target_users_per_inbound??10000)+'"></label><label>User quota — MB expression, 0 = unlimited<input name="quota_expr" value="'+esc(quotaMB)+'" placeholder="1024 or 10*100"></label><label>User lifetime — minute expression, 0 = no expiry<input name="lifetime_expr" value="'+esc(lifeMin)+'" placeholder="60 or 5*60"></label><label>Device limit (0 = unlimited)<input name="device_limit" type="number" min="0" value="'+esc(x.device_limit||0)+'"></label><label>Users created / second<input name="users_per_second" type="number" min="1" value="'+esc(x.users_per_second||100)+'"></label><label>SNI selection<select name="sni_selection_mode"><option value="scored">Automatic — scanner score</option><option value="manual">Manual</option></select></label><label>Manual SNIs (one per line)<textarea name="manual_snis" rows="4" placeholder="www.cloudflare.com">'+esc((x.manual_snis||[]).join('\n'))+'</textarea></label>';
  $('#modalFields [name="sni_selection_mode"]').value=x.sni_selection_mode||'scored';$('#modalError').textContent='';$('#modal').showModal();
  $('#modalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),ports=String(f.get('ports')||'').split(',').map(v=>Number(v.trim())).filter(Number.isInteger),sn=String(f.get('manual_snis')||'').split(/\r?\n|,/).map(v=>v.trim()).filter(Boolean);if(!ports.length){$('#modalError').textContent='Enter at least one port.';return}if(ports.some(p=>p<1||p>65535)||new Set(ports).size!==ports.length){$('#modalError').textContent='Ports must be unique values from 1 to 65535.';return}const expr=/^\s*\d+(?:\s*\*\s*\d+)*\s*$/;if(!expr.test(String(f.get('quota_expr')))||!expr.test(String(f.get('lifetime_expr')))){$('#modalError').textContent='Quota and lifetime allow whole numbers and multiplication only, e.g. 10*100 or 5*60.';return}const body={enabled:f.get('enabled')==='on',ports,target_users_per_inbound:Number(f.get('target_users_per_inbound')),user_quota_expression:String(f.get('quota_expr')),user_lifetime_expression:String(f.get('lifetime_expr')),device_limit:Number(f.get('device_limit')),users_per_second:Number(f.get('users_per_second')),sni_selection_mode:f.get('sni_selection_mode'),manual_snis:sn};try{await api('/api/v1/configs',{method:'PUT',body:JSON.stringify(body)});$('#modal').close();load('configs')}catch(err){$('#modalError').textContent=err.message}};
 }catch(e){alert(e.message)}
}
window.editConfig=async()=>{const list=cache.configs||await api('/api/v1/configs');openConfigForm(list[0]||null)};

document.addEventListener('click',e=>{const b=e.target.closest('[data-action="edit-config"]');if(b)window.editConfig()});
window.deleteAllCapacityClients=async()=>{if(!confirm('Delete ALL managed Reality clients from every eligible Sanaei panel? Reality creation will be disabled and stay disabled.'))return;if(!confirm('This is destructive. Continue deleting all clients?'))return;const btn=document.querySelector('[data-action="delete-all-capacity-clients"]'),old=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Starting...'}try{const start=await api('/api/v1/config-capacity/delete-all-clients',{method:'POST'});const id=start.job_id;if(!id)throw new Error('missing job id');for(;;){const j=await api('/api/v1/config-capacity/cleanup/'+encodeURIComponent(id));if(btn)btn.textContent='Deleting '+j.completed+' / '+j.total+' · OK '+j.succeeded+' · Fail '+j.failed;if(j.status==='done'){toast('Cleanup complete: '+j.succeeded+' succeeded, '+j.failed+' failed',j.failed?'error':'ok');await load('configs');break}await new Promise(r=>setTimeout(r,1000))}}catch(e){toast('Cleanup failed: '+e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=old||'Delete All Clients'}}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="delete-all-capacity-clients"]');if(b)deleteAllCapacityClients()});



