window.loadOutput=async(expiry=false)=>{let path='/api/v1/output';if(expiry){const input=document.querySelector('#outputExpiryMinutes'),minutes=Math.max(1,Math.min(1440,Number(input?.value||4)));if(input)input.value=String(minutes);localStorage.setItem('outputExpiryMinutes',String(minutes));path+='?expires_within_minutes='+encodeURIComponent(minutes)}const win=window.open('about:blank','_blank');if(!win){toast('Popup blocked. Allow popups for this panel.','error');return}win.document.open();win.document.write('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>DO Bot Output</title><style>body{margin:16px;background:#081122;color:#eef3ff;font:13px/1.55 monospace;word-break:break-all;white-space:pre-wrap}</style><body>Loading configs...</body>');win.document.close();try{const r=await fetch(path,{headers:headers(false),cache:'no-store'});if(r.status===401){win.close();logout();throw Error('Panel session expired. Please sign in again.')}if(!r.ok)throw Error(await r.text());const t=await r.text();win.document.body.textContent=t.trim()||'No matching Reality configs found.'}catch(e){win.document.body.textContent='Output failed: '+e.message}};
